from rich.traceback import Traceback
import sys

def test_exception_notes():
    try:
        try:
            1/0
        except Exception as e:
            e.add_note("Note 1")
            e.add_note("Note 2")
            raise
    except Exception:
        console = Console(record=True)
        console.print_exception()
        print(console.export())

if __name__ == "__main__":
    test_exception_notes()

